func newEDIMappingProfile() unsafe.Pointer { return unsafe.Pointer(new(edi.EDIMappingProfile)) }

func newNEDIMappingProfile(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]edi.EDIMappingProfile, n)))
}

func ptrEDIMappingProfile(p unsafe.Pointer, c int32) any {
	r := (*edi.EDIMappingProfile)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.EDIPartnerID))
	case 4:
		return &r.Name
	case 5:
		return &r.Description
	case 6:
		return &r.SearchVector
	case 7:
		return &r.Rank
	case 8:
		return &r.Version
	case 9:
		return &r.CreatedAt
	case 10:
		return &r.UpdatedAt
	}
	return nil
}

func valueEDIMappingProfile(p unsafe.Pointer, c int32) any {
	r := (*edi.EDIMappingProfile)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.EDIPartnerID)
	case 4:
		return r.Name
	case 5:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 6:
		return r.SearchVector
	case 7:
		return r.Rank
	case 8:
		return r.Version
	case 9:
		return r.CreatedAt
	case 10:
		return r.UpdatedAt
	}
	return nil
}

func attachEDIMappingProfile(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*edi.EDIMappingProfile)(p)
	switch rel {
	case 0:
		r.Partner = (*edi.EDIPartner)(child)
	case 1:
		r.Entries = append(r.Entries, (*edi.EDIMappingProfileItem)(child))
	}
}

