func ptrEDIPartner(p unsafe.Pointer, c int32) any {
	r := (*edi.EDIPartner)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.Kind))
	case 4:
		return (*string)(unsafe.Pointer(&r.Status))
	case 5:
		return &r.Code
	case 6:
		return &r.Name
	case 7:
		return &r.Description
	case 8:
		return (*string)(unsafe.Pointer(&r.InternalOrganizationID))
	case 9:
		return (*string)(unsafe.Pointer(&r.EDIConnectionID))
	case 10:
		return (*string)(unsafe.Pointer(&r.CustomerID))
	case 11:
		return (*string)(unsafe.Pointer(&r.DefaultTransportID))
	case 12:
		return (*string)(unsafe.Pointer(&r.DefaultMappingProfileID))
	case 13:
		return &r.Timezone
	case 14:
		return &r.Country
	case 15:
		return &r.ContactName
	case 16:
		return &r.ContactEmail
	case 17:
		return &r.ContactPhone
	case 18:
		return &r.EnabledForInbound
	case 19:
		return &r.EnabledForOutbound
	case 20:
		return &r.Settings
	case 21:
		return &r.SearchVector
	case 22:
		return &r.Rank
	case 23:
		return &r.Version
	case 24:
		return &r.CreatedAt
	case 25:
		return &r.UpdatedAt
	}
	return nil
}

func valueEDIPartner(p unsafe.Pointer, c int32) any {
	r := (*edi.EDIPartner)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.Kind)
	case 4:
		return string(r.Status)
	case 5:
		return r.Code
	case 6:
		return r.Name
	case 7:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 8:
		if r.InternalOrganizationID == "" {
			return nil
		}
		return string(r.InternalOrganizationID)
	case 9:
		if r.EDIConnectionID == "" {
			return nil
		}
		return string(r.EDIConnectionID)
	case 10:
		if r.CustomerID == "" {
			return nil
		}
		return string(r.CustomerID)
	case 11:
		if r.DefaultTransportID == "" {
			return nil
		}
		return string(r.DefaultTransportID)
	case 12:
		if r.DefaultMappingProfileID == "" {
			return nil
		}
		return string(r.DefaultMappingProfileID)
	case 13:
		if r.Timezone == "" {
			return nil
		}
		return r.Timezone
	case 14:
		return r.Country
	case 15:
		if r.ContactName == "" {
			return nil
		}
		return r.ContactName
	case 16:
		if r.ContactEmail == "" {
			return nil
		}
		return r.ContactEmail
	case 17:
		if r.ContactPhone == "" {
			return nil
		}
		return r.ContactPhone
	case 18:
		return r.EnabledForInbound
	case 19:
		return r.EnabledForOutbound
	case 20:
		if r.Settings == nil {
			return keel.EmptyJSONObject
		}
		return r.Settings
	case 21:
		return r.SearchVector
	case 22:
		return r.Rank
	case 23:
		return r.Version
	case 24:
		return r.CreatedAt
	case 25:
		return r.UpdatedAt
	}
	return nil
}

func attachEDIPartner(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*edi.EDIPartner)(p)
	switch rel {
	case 0:
		r.InternalOrganization = (*tenant.Organization)(child)
	case 1:
		r.Customer = (*customer.Customer)(child)
	case 2:
		r.Connection = (*edi.EDIConnection)(child)
	case 3:
		r.DefaultTransport = (*edi.EDICommunicationProfile)(child)
	case 4:
		r.MappingProfile = (*edi.EDIMappingProfile)(child)
	case 5:
		r.MappingEntries = append(r.MappingEntries, (*edi.EDIMappingProfileItem)(child))
	}
}

